param(
    [Parameter(Mandatory = $false)]
    [string] $Text = "",

    [Parameter(Mandatory = $false)]
    [string[]] $Paths = @()
)

$forbidden = @(
    'generated with',
    'generated by ai',
    'ai-generated',
    'llm-generated',
    'co-authored-by: opencode',
    'co-authored-by: claude',
    'co-authored-by: chatgpt',
    'co-authored-by: copilot',
    'chatgpt',
    'copilot',
    'ai assistant',
    'openai',
    'anthropic'
)

$sources = @()
if (-not [string]::IsNullOrWhiteSpace($Text)) {
    $sources += [pscustomobject]@{ Name = 'input'; Content = $Text }
}

foreach ($path in $Paths) {
    if (-not (Test-Path -LiteralPath $path)) {
        Write-Error "Path not found: $path"
        exit 1
    }

    $sources += [pscustomobject]@{
        Name = $path
        Content = Get-Content -LiteralPath $path -Raw
    }
}

$found = $false
foreach ($source in $sources) {
    foreach ($phrase in $forbidden) {
        if ($source.Content -match [regex]::Escape($phrase)) {
            Write-Error "Forbidden attribution phrase '$phrase' found in $($source.Name)."
            $found = $true
        }
    }
}

if ($found) {
    exit 1
}

Write-Output "No forbidden attribution phrases found."
